(() => {
  const SAVE_KEY = 'crimsonVeilSave_v1';
  const ranks = ['Low Undead', 'Lower Vampire', 'Vampire', 'Lord', 'High Lord', 'Overlord'];
  const people = [
    {id:'yselle',name:'Sister Yselle',initial:'Y',faction:'THE VEILED COURT',place:'Hollow Shrine',x:62,y:60,quest:'The Bell Beneath',hook:'bell',clue:'a bell tolling below the drowned chapel',finish:['bell','chapel','drowned','toll'],intro:'You wake beneath a ruined shrine, your mouth full of grave-dust. A veiled woman watches from the steps. “Do not mistake your second breath for a gift.”',questText:'Yselle heard a bell beneath the drowned chapel. Find what answers it.',doneText:'You return with the bell’s name. Yselle lowers her veil, and for the first time, calls you kin.',memory:'She studies the pulse in your throat.'},
    {id:'rook',name:'Rook Vale',initial:'R',faction:'DHAMPIR OUTCASTS',place:'Bamboo Crossing',x:28,y:66,quest:'A Name Unburied',hook:'name',clue:'the name the hunters erased from their ledger',finish:['name','ledger','hunter','record'],intro:'A lean stranger steps from the bamboo, silver knife low. “You smell like a fresh grave. I can help with that—or make it permanent.”',questText:'Rook has stolen a hunter ledger. Ask whose name was cut from its pages.',doneText:'The name is restored to the ledger. Rook’s guarded grin turns almost sincere.',memory:'Their knife stays low, but never leaves their hand.'},
    {id:'mara',name:'Mara Sable',initial:'M',faction:'THE BLOOD MERCHANTS',place:'Redwater Market',x:79,y:54,quest:'The Last Red Lantern',hook:'lantern',clue:'the lantern that marks a safe road through Redwater',finish:['lantern','redwater','safe road','oil'],intro:'A merchant in crimson silk weighs a vial against the moonlight. “First taste is on the house. First debt is forever.”',questText:'Mara’s last red lantern has gone dark. Find its keeper in Redwater.',doneText:'The red lantern burns again over Redwater. Mara pours you a measure without naming a price.',memory:'She is already calculating what your silence is worth.'},
    {id:'vesper',name:'Vesper Ardent',initial:'V',faction:'THE NIGHT COURT',place:'Gloam Court',x:69,y:39,quest:'An Invitation in Ash',hook:'invitation',clue:'the ash-sealed invitation to the Night Court',finish:['invitation','ash','court','seal'],intro:'A noble in a silver half-mask inclines their head by a fraction. “The court has no place for the newly dead. Yet.”',questText:'Vesper’s invitation was burned before the court could meet. Recover its ash-seal.',doneText:'The invitation is accepted. Vesper’s formal bow carries the weight of an equal.',memory:'They remember every slight as if it were a title.'},
    {id:'ilyan',name:'Old Ilyan',initial:'I',faction:'THE SLEEPING ELDERS',place:'Drowned Cathedral',x:40,y:39,quest:'The Heart Below',hook:'heart',clue:'what beats inside the sleeping elder beneath the cathedral',finish:['heart','elder','cathedral','sleep'],intro:'A voice speaks from the dark inside a stone sarcophagus. “Little hunger. Tell me: does the moon still grieve?”',questText:'An elder dreams beneath the drowned cathedral. Learn what stirs its heart.',doneText:'The elder opens one eye. “At last,” he whispers. “One who listened.”',memory:'He knew your name before you did.'}
  ];
  const locations = [
    {name:'The Hollow Shrine',short:'HOLLOW SHRINE',subtitle:'Where the dead remember how to breathe.',x:48,y:58},
    {name:'Bamboo Crossing',short:'BAMBOO CROSSING',subtitle:'A silver blade waits between the stalks.',x:27,y:63},
    {name:'Redwater Market',short:'REDWATER MARKET',subtitle:'Every hunger has its price.',x:78,y:52},
    {name:'Drowned Cathedral',short:'DROWNED CATHEDRAL',subtitle:'The oldest silence is beginning to stir.',x:38,y:39},
    {name:'Gloam Court',short:'GLOAM COURT',subtitle:'The court remembers who was made to kneel.',x:68,y:38}
  ];
  const mainBeats = [
    {title:'The Hunger Within',kicker:'A THREAD TIGHTENS',body:'A voice beneath the shrine calls you by a name you have never heard. Sister Yselle offers no comfort—only a choice: master your hunger, or let it master the valley.'},
    {title:'A Place at the Threshold',kicker:'THE VEIL OPENS',body:'The lower district sees you now. Not as prey, perhaps—but as a problem that may become useful. The blood court is gathering. Find the ones who still remember the old laws.'},
    {title:'The Red Covenant',kicker:'A DEBT COMES DUE',body:'Your blood answers the moon with a language older than the court. Claim a territory in the name of the night, and learn what the elders fear to say aloud.'},
    {title:'A Lord in the Mist',kicker:'POWER TAKES ROOT',body:'The lesser houses bend the knee, but their loyalty is thinner than fog. A council seat waits among the black pillars. Take it—and decide what the night is allowed to become.'},
    {title:'The Dayless Throne',kicker:'THE HUNT TURNS',body:'The mortal orders have named you the threat. A High Lord may answer with blood, or offer the hunters a bargain. Either choice will be remembered at the final court.'},
    {title:'Crown of the Long Night',kicker:'THE FINAL SUMMONS',body:'The Overlord’s crown is empty. The Night Court gathers at the Gloam Basilica. This is the last door. The world you leave behind will be the world that answers.'}
  ];
  const endingRushed = {kicker:'THE LESSER CROWN',title:'Overlord of the Night',body:'The court bows. The old houses name you Overlord, and the world learns to fear your shadow. But the throne is colder than the grave, and every legend remains a locked door. You have conquered the night. It does not yet revere you.'};
  const endingTrue = {kicker:'THE VEIL REMEMBERS',title:'Vampress',body:'A crimson fracture opens across the heavens. Every path you walked returns to the throne: the bell, the name, the lantern, the ash-seal, the elder’s waking heart. Those you stood beside gather at your back. The hidden throne recognizes the life you lived—and the night kneels, not from fear, but in reverence. The Vampress has returned.'};
  let state = load();
  let currentPerson = null;
  let toastTimer;
  function fresh(){return {rank:0,mainStep:0,blood:36,location:0,playerX:48,quests:{},people:{},seen:{},memory:{},completed:false,ending:null,clock:0};}
  function load(){try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY));return saved?Object.assign(fresh(),saved):fresh()}catch{return fresh()}}
  function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state));render()}
  function render(){
    const rank = ranks[Math.min(state.rank,5)];
    document.getElementById('rankLabel').textContent=rank.toUpperCase();
    document.getElementById('bloodFill').style.width=state.blood+'%';document.getElementById('bloodText').textContent=state.blood+' / 100';
    document.getElementById('objectiveText').textContent=state.completed?'The night remembers what you became':state.mainStep>=6?'The final court awaits at Gloam Court':mainObjectives[state.mainStep];
    document.getElementById('journalCount').textContent=Object.values(state.quests).filter(q=>q.done).length;
    document.getElementById('sideCount').textContent=`${Object.values(state.quests).filter(q=>q.done).length} / ${people.length}`;
    document.querySelector('.quest-progress span').style.width=Math.min(100,(state.mainStep/6)*100)+'%';
    const c=document.querySelector('.quest-foot span');c.textContent=`✦  ${Math.min(state.mainStep,6)} / 6 steps`;
    const next=document.querySelector('.quest-foot button');next.textContent=state.mainStep>=6?'BEGIN FINAL MISSION ↗':'CONTINUE ↗';
    document.getElementById('abilityMist').classList.toggle('locked',state.rank<1);document.querySelector('#abilityMist small').textContent=state.rank>=1?'EQUIPPED':'LOCKED';
    document.getElementById('abilityClaw').classList.toggle('locked',false);document.querySelector('#abilityClaw small').textContent='UNLOCKED';
    const ranksEl=document.getElementById('rankList');ranksEl.innerHTML=ranks.map((r,i)=>`<div class="rank-mini ${i===state.rank?'current':i<state.rank?'passed':''}"><span class="rank-num">${i<state.rank?'✓':i+1}</span><span>${r}</span></div>`).join('');
    document.getElementById('questList').innerHTML=people.map(p=>{const q=state.quests[p.id];return q?`<div class="quest-row ${q.done?'complete':''}" data-person="${p.id}"><span class="quest-icon">${q.done?'✓':'✧'}</span><span><b>${p.quest}</b><small>${q.done?'THREAD RESOLVED':`FOLLOW THE WHISPER · ${p.place.toUpperCase()}`}</small></span><span class="quest-arrow">↗</span></div>`:''}).join('')||'<div class="quest-empty">No side threads have surfaced yet.<br><small>Speak with the people you meet.</small></div>';
    document.getElementById('peopleList').innerHTML=people.map(p=>{const m=state.people[p.id]||{affinity:0};const met=state.seen[p.id];const q=state.quests[p.id];return `<div class="person-row" data-person="${p.id}"><span class="person-avatar">${p.initial}</span><span><b>${p.name}</b><small>${met?(q?.done?'THREAD RESOLVED':m.affinity>=3?'A TRUSTED ALLY':'REMEMBERS YOUR WORDS'):'SOMEWHERE IN THE VEIL'}</small></span><span class="person-status">${met?'↗':'·'}</span></div>`}).join('');
    document.getElementById('worldList').innerHTML=locations.map((l,i)=>`<div class="world-place ${i===state.location?'current':''}" data-location="${i}"><span><b>${l.name}</b><small>${i===state.location?'YOU ARE HERE':'TRAVEL INTO THE MIST'}</small></span><span>↗</span></div>`).join('');
    document.getElementById('locationTitle').textContent=locations[state.location].name;document.getElementById('locationSubtitle').textContent=locations[state.location].subtitle;
    const available=people.filter(p=>p.place===locations[state.location].name);
    document.getElementById('nearbyName').textContent=available[0]?.name||'No one is near';document.getElementById('interactPrompt').style.opacity=available.length?1:.45;
    document.getElementById('playerToken').style.left=state.playerX+'%';
    document.getElementById('locationPins').innerHTML=people.filter(p=>p.place!==locations[state.location].name).map(p=>`<button class="pin" data-person="${p.id}" style="left:${p.x}%;top:${p.y}%"><i></i>${p.name.split(' ')[0]}</button>`).join('');
    document.getElementById('locationSwitcher').innerHTML=locations.map((l,i)=>`<button class="${i===state.location?'active':''}" data-location="${i}">${l.short}</button>`).join('');
    document.getElementById('memoryLine').textContent=currentPerson?memoryFor(currentPerson):'She studies the pulse in your throat.';
    document.querySelector('.objective-mark').textContent=state.completed?'✧':'✦';
    document.getElementById('clock').textContent=state.clock%2?'00:16':'23:48';
    bindDynamic();
  }
  const mainObjectives=['Find your place among the living dead','Enter the lower district and face the night court','Claim a territory and learn the red covenant','Take your seat among the ruling houses','Choose the fate of the mortal hunters','Answer the final summons at Gloam Court'];
  function bindDynamic(){document.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>openPerson(people.find(p=>p.id===el.dataset.person)));document.querySelectorAll('[data-location]').forEach(el=>el.onclick=()=>travel(Number(el.dataset.location)));}
  function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
  function travel(index){if(index<0||index>=locations.length)return;state.location=index;state.playerX=locations[index].x;state.clock++;save();toast(`You slip through the mist to ${locations[index].name}.`)}
  function nearestPerson(){return people.find(p=>p.place===locations[state.location].name)}
  function openPerson(person){if(!person)return;currentPerson=person;state.seen[person.id]=true;const prior=state.memory[person.id]||[];document.getElementById('npcName').textContent=person.name;document.getElementById('npcFaction').textContent=person.faction;document.getElementById('npcPortrait').innerHTML=`<span>${person.initial}</span>`;const m=state.people[person.id]||{affinity:0,insults:0};document.getElementById('npcMood').textContent=m.insults?'GUARDED · YOUR WORDS HAVE A WEIGHT':m.affinity>=3?'A TRUSTED ALLY · THE NIGHT REMEMBERS':'WATCHFUL · REMEMBERS YOUR WORDS';const log=document.getElementById('dialogueLog');log.innerHTML='';if(prior.length){prior.slice(-4).forEach(item=>appendMessage(item.who,item.text,false));appendMessage('npc',rankGreeting(person),false)}else appendMessage('npc',person.intro,false);document.getElementById('dialogueModal').classList.add('open');document.getElementById('dialogueModal').setAttribute('aria-hidden','false');document.getElementById('chatInput').focus();save()}
  function rankGreeting(p){if(state.rank>=4)return `“${state.rank===5?'Overlord':'High Lord'},” ${p.name.split(' ')[0]} says, with a careful dip of the head. “The night has altered its manners around you.”`;if(state.rank>=2)return `“You carry yourself differently now,” ${p.name.split(' ')[0]} says. “The court has begun to notice.”`;if(state.rank===1)return `“You have earned a little room to stand,” ${p.name.split(' ')[0]} says. “Do not spend it carelessly.”`;return p.memory}
  function appendMessage(who,text,store=true){const el=document.createElement('div');el.className=`message ${who==='player'?'player':'npc'}`;el.textContent=text;document.getElementById('dialogueLog').appendChild(el);document.getElementById('dialogueLog').scrollTop=99999;if(store&&currentPerson){state.memory[currentPerson.id]??=[];state.memory[currentPerson.id].push({who,text});state.memory[currentPerson.id]=state.memory[currentPerson.id].slice(-18)}}
  function memoryFor(p){const q=state.quests[p.id];if(q?.done)return 'They remember the night you stood beside them.';if(q)return 'A promise hangs between you, not yet fulfilled.';return p.memory}
  const stopMeta=/\b(game|player|quest menu|developer|code|computer|chatgpt|ai|npc|prompt|system prompt|real world|real life|controls|walkthrough)\b/i;
  function responseFor(p,text){const t=text.toLowerCase();const m=state.people[p.id]||{affinity:0,insults:0};state.people[p.id]=m;let reply='';
    if(stopMeta.test(t)){reply=`${p.name.split(' ')[0]} regards you with a thin, puzzled smile. “I know nothing of such machinery. Speak to me of the night, or let the silence answer.”`;}
    else if(/\b(hate|kill you|threat|destroy|kneel|obey|submit)\b/.test(t)){m.insults++;m.affinity=Math.max(0,m.affinity-1);reply=state.rank>=4?`“Power has made your threats less interesting, ${ranks[state.rank]}. Choose your next words with care.”`:`${p.name.split(' ')[0]}’s expression hardens. “Threaten me again, and I will remember it longer than you live.”`;}
    else if(/\b(sorry|apolog|forgive|peace)\b/.test(t)){m.affinity=Math.min(5,m.affinity+1);reply='A little of the tension leaves their shoulders. “An apology is only a beginning. Still, I will remember that you offered one.”';}
    else if(/\b(thank|kind|friend|trust|respect|beautiful|wise|admire|love)\b/.test(t)){m.affinity=Math.min(5,m.affinity+1);reply=`${p.name.split(' ')[0]} lets the words settle. “You speak more gently than most of the night. I will remember it.”`;}
    else if(/\b(gift|offer|give you|present|vial)\b/.test(t)){if(state.blood>=8){state.blood-=8;m.affinity=Math.min(5,m.affinity+2);reply='They accept the blood-vial, weighing its crimson glow. “A generous gesture. I will not forget who offered it when the night was lean.”';}else reply='They glance at your empty hands. “Keep your last strength. The night will ask enough of you.”';}
    else if(/\b(promise|swear|pledge|oath)\b/.test(t)){m.affinity=Math.min(5,m.affinity+1);reply='“Then let the dark bear witness,” they say. “A promise is a door. Whether it opens or closes is yours to decide.”';}
    else if(/\b(rumor|secret|legend|tell me|what do you know|lore|heard|story|ask about)\b/.test(t)){const q=state.quests[p.id];if(!q){state.quests[p.id]={done:false};reply=`${p.name.split(' ')[0]} pauses, then leans closer. “There is something I have not told the court. It concerns ${p.clue}. Will you see it through?”`;m.affinity=Math.min(5,m.affinity+1)}else if(q.done)reply=p.doneText+' “Some stories only end when we stop telling them.”';else reply=`“You remember,” they say. “${p.questText} Ask after ${p.hook}, and I will tell you what I can.”`;}
    else if(state.quests[p.id]&&!state.quests[p.id].done&&p.finish.some(k=>t.includes(k))){const q=state.quests[p.id];q.done=true;m.affinity=Math.min(5,m.affinity+2);state.blood=Math.min(100,state.blood+12);reply=p.doneText+' “The night is not done with us yet.”';toast('A thread in the dark has been mended.');}
    else if(/\b(hungry|blood|feed|thirst)\b/.test(t)){reply=state.rank>=3?'“The blood answers you now. You need not beg the night for its strength.”':'“Hunger is an honest tutor. Feed only from those who would hunt you, and it may teach you restraint.”';}
    else if(/\b(rank|lord|overlord|vampress|throne)\b/.test(t)){reply=p.id==='ilyan'?'His ancient eyes open a fraction. “There is a throne older than the Overlord’s. It does not answer to strength. It answers to those who remember the names of the forgotten.”':`“Titles are borrowed from the night,” ${p.name.split(' ')[0]} says. “What matters is who still speaks to you when the court has gone quiet.”`;}
    else if(/\b(lie|lying|lied|truth)\b/.test(t)){m.insults++;reply='Their eyes narrow as if weighing your heartbeat. “Truth and lies both leave a taste. Be certain you know which one you have offered.”';}
    else if(/\b(hello|hi\b|greet|hail|evening)\b/.test(t)){m.affinity=Math.min(5,m.affinity+1);reply=state.rank>=3?`“The night is improved by your arrival, ${ranks[state.rank]}.”`: `“And to you,” ${p.name.split(' ')[0]} replies. “The night has a way of bringing us together.”`;}
    else if(state.quests[p.id]&&!state.quests[p.id].done)reply=`“I have not forgotten what I asked of you,” ${p.name.split(' ')[0]} says. “${p.questText}”`;
    else reply=`${p.name.split(' ')[0]} listens, then answers: “There is more in those words than you think. Tell me—what do you seek in this long night?”`;
    return reply;
  }
  document.getElementById('chatForm').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('chatInput');const text=input.value.trim();if(!text||!currentPerson)return;appendMessage('player',text);input.value='';const reply=responseFor(currentPerson,text);appendMessage('npc',reply);document.getElementById('memoryLine').textContent=memoryFor(currentPerson);const m=state.people[currentPerson.id];document.getElementById('npcMood').textContent=m.insults?'GUARDED · YOUR WORDS HAVE A WEIGHT':m.affinity>=3?'A TRUSTED ALLY · THE NIGHT REMEMBERS':'WATCHFUL · REMEMBERS YOUR WORDS';save();});
  function closeModal(id){document.getElementById(id).classList.remove('open');document.getElementById(id).setAttribute('aria-hidden','true')}
  document.getElementById('closeDialogue').onclick=()=>closeModal('dialogueModal');document.getElementById('dialogueModal').addEventListener('click',e=>{if(e.target.id==='dialogueModal')closeModal('dialogueModal')});
  document.getElementById('interactPrompt').onclick=()=>{const p=nearestPerson();if(p)openPerson(p);else toast('Only the mist answers here. Choose another place.')};
  document.getElementById('moveLeft').onclick=()=>{state.playerX=Math.max(8,state.playerX-8);save()};document.getElementById('moveRight').onclick=()=>{state.playerX=Math.min(90,state.playerX+8);save()};
  document.getElementById('abilityDrain').onclick=()=>{if(state.blood>=100){toast('Your blood is full.');return}state.blood=Math.min(100,state.blood+15);save();toast('You draw strength from the red veil. Blood +15.')};
  document.getElementById('abilityMist').onclick=()=>{if(state.rank<1){toast('Mist-form waits beyond the first ascent.');return}state.playerX=state.playerX>50?26:74;save();toast('You dissolve into mist and reform across the veil.')};
  document.getElementById('abilityClaw').onclick=()=>{toast('You cling to the shrine wall, then drop silently into the mist.')};
  document.getElementById('objectiveNext').onclick=()=>advanceMain();document.getElementById('continueQuest').onclick=()=>advanceMain();
  function advanceMain(){if(state.completed){showStory(state.ending==='true'?endingTrue:endingRushed);return}if(state.mainStep<6){const beat=mainBeats[state.mainStep];state.mainStep++;state.rank=Math.min(5,state.mainStep-1);state.blood=Math.min(100,state.blood+8);state.clock++;save();showStory(beat);return}const completionist=people.every(p=>state.quests[p.id]?.done&&(state.people[p.id]?.affinity||0)>=3);state.ending=completionist?'true':'rushed';state.completed=true;if(completionist){state.rank=5;showStory(endingTrue)}else showStory(endingRushed);save()}
  function showStory(beat){document.getElementById('storyKicker').textContent=beat.kicker;document.getElementById('storyTitle').textContent=beat.title;document.getElementById('storyBody').textContent=beat.body;document.getElementById('storyModal').classList.add('open');document.getElementById('storyModal').setAttribute('aria-hidden','false')}
  document.getElementById('closeStory').onclick=()=>closeModal('storyModal');document.getElementById('storyContinue').onclick=()=>closeModal('storyModal');document.getElementById('storyModal').addEventListener('click',e=>{if(e.target.id==='storyModal')closeModal('storyModal')});
  document.querySelectorAll('.tab').forEach(button=>button.onclick=()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));document.querySelectorAll('.tab-content').forEach(c=>c.classList.add('hidden'));button.classList.add('active');document.getElementById('tab-'+button.dataset.tab).classList.remove('hidden')});
  document.querySelectorAll('.rail-link').forEach(button=>button.onclick=()=>{document.querySelectorAll('.rail-link').forEach(b=>b.classList.remove('active'));button.classList.add('active');const tab=button.dataset.panel;if(tab==='journal'||tab==='map'||tab==='codex'){document.querySelector(`.tab[data-tab="${tab==='map'?'world':tab==='codex'?'people':'journal'}"]`).click();document.getElementById('rightPanel').scrollIntoView({behavior:'smooth',block:'nearest'})}});
  document.getElementById('menuToggle').onclick=()=>{document.getElementById('rightPanel').scrollIntoView({behavior:'smooth'});toast('The field journal is open.')};document.getElementById('brandHome').onclick=()=>travel(0);
  document.getElementById('soundToggle').onclick=e=>{e.currentTarget.classList.toggle('on');toast(e.currentTarget.classList.contains('on')?'The night hums around you.':'The night falls quiet.')};
  document.getElementById('voiceButton').onclick=()=>{const last=state.memory[currentPerson?.id]?.filter(x=>x.who==='npc').slice(-1)[0]?.text;if(!last)return;if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(last))}else toast('Voice playback is not available in this browser.')};
  let recognition=null;document.getElementById('micButton').onclick=()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Speech input is not available in this browser.');return}if(recognition){recognition.stop();recognition=null;return}recognition=new SpeechRecognition();recognition.lang='en-US';recognition.interimResults=false;const btn=document.getElementById('micButton');btn.classList.add('recording');recognition.onresult=e=>{document.getElementById('chatInput').value=e.results[0][0].transcript;document.getElementById('chatInput').focus()};recognition.onend=()=>{btn.classList.remove('recording');recognition=null};recognition.start()};
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal('dialogueModal');closeModal('storyModal')}if(e.key.toLowerCase()==='e'&&document.activeElement.tagName!=='INPUT'){const p=nearestPerson();if(p)openPerson(p)}if(e.key==='ArrowLeft')document.getElementById('moveLeft').click();if(e.key==='ArrowRight')document.getElementById('moveRight').click();if(e.key.toLowerCase()==='q')document.getElementById('abilityDrain').click()});
  render();
})();

